  {
    "name": "0008_fx_rates.sql",
    "sql": "-- Control-plane migration 0008: dollar-to-rupee rates by date (ADR-018). Idempotent.\n-- A tax invoice converts the price at the rate for the day the customer paid. One row per day. An operator's own entry always\n-- wins over an automatic one for the same day. Nothing is invented: a day with no row uses the latest earlier day (up to a week),\n-- and past that the invoice falls back to the manual rate in Settings, and says so.\ncreate table if not exists public.fx_rates (\n  rate_date  date primary key,\n  buy        numeric(10,4) not null check (buy > 0 and buy < 100000),\n  sell       numeric(10,4) not null check (sell > 0 and sell < 100000),\n  source     text not null check (length(source) between 2 and 40),         -- 'manual', 'forex.pk'\n  note       text check (note is null or length(note) <= 200),\n  entered_by uuid,\n  fetched_at timestamptz not null default now(),\n  check (sell >= buy)\n);\ncreate index if not exists fx_rates_source_idx on public.fx_rates(source, rate_date desc);\n\nalter table public.fx_rates enable row level security;\ndo $$\ndeclare r text;\nbegin\n  foreach r in array array['anon', 'authenticated'] loop\n    if exists (select 1 from pg_roles where rolname = r) then execute format('revoke all on table public.fx_rates from %I', r); end if;\n  end loop;\nend $$;\n\ndrop trigger if exists fx_rates_audit on public.fx_rates;\ncreate trigger fx_rates_audit after insert or update or delete on public.fx_rates for each row execute function public.platform_audit_trigger();\n",
    "checksum": "5c06af0a6d392089ef67fce0a2da7e071b3f3976cf23a7030d340a82dfe13aed"
  },
  {
    "name": "0009_close_api_grants.sql",
    "sql": "-- Control-plane migration 0009: the public API roles hold no privileges on our tables. Idempotent.\n-- Supabase grants anon and authenticated full access to every table made in the public schema, and the first tables here were made before\n-- each migration revoked it. Row security already keeps those roles out (every table has it on, with no policy), so nothing was exposed;\n-- this removes the privileges as well, so a table made without row security would still be closed. The application connects as its own\n-- role and is not affected. Storage keeps working: its rules go through functions in app_private, which run with their own rights.\ndo $$\ndeclare r text;\nbegin\n  foreach r in array array['anon', 'authenticated'] loop\n    if exists (select 1 from pg_roles where rolname = r) then\n      execute format('revoke all on all tables in schema public from %I', r);\n      execute format('revoke all on all sequences in schema public from %I', r);\n      -- tables and sequences made from now on start closed, whoever makes them\n      execute format('alter default privileges in schema public revoke all on tables from %I', r);\n      execute format('alter default privileges in schema public revoke all on sequences from %I', r);\n      if exists (select 1 from pg_roles where rolname = 'postgres') then\n        execute format('alter default privileges for role postgres in schema public revoke all on tables from %I', r);\n        execute format('alter default privileges for role postgres in schema public revoke all on sequences from %I', r);\n      end if;\n    end if;\n  end loop;\nend $$;\n",
    "checksum": "dab60c7ad9d8d064b03e22ed8414dc7122b59c5e1ef444db4fc95699d0f389d0"
  },
  {
    "name": "0010_contact_messages.sql",
    "sql": "-- Control-plane migration 0010: messages from the public Contact us page (ADR-021). Idempotent.\n-- Anyone can leave a message, so the table holds only what the person typed and a status. It is read and marked handled by the\n-- operator through the application; the public API roles have no access (row security on, privileges revoked).\ncreate table if not exists public.contact_messages (\n  id         uuid primary key default gen_random_uuid(),\n  name       text not null check (char_length(name) between 2 and 120),\n  email      text not null check (char_length(email) between 5 and 200),\n  company    text check (company is null or char_length(company) <= 120),\n  topic      text not null check (topic in ('sales', 'support', 'billing', 'other')),\n  message    text not null check (char_length(message) between 10 and 2000),\n  status     text not null default 'new' check (status in ('new', 'handled')),\n  created_at timestamptz not null default now(),\n  handled_at timestamptz,\n  handled_by uuid\n);\ncreate index if not exists contact_messages_status_idx on public.contact_messages(status, created_at desc);\n\nalter table public.contact_messages enable row level security;\ndo $$\ndeclare r text;\nbegin\n  foreach r in array array['anon', 'authenticated'] loop\n    if exists (select 1 from pg_roles where rolname = r) then execute format('revoke all on table public.contact_messages from %I', r); end if;\n  end loop;\nend $$;\n",
    "checksum": "361c15d3b444b4d5dd30e7ad18e6db34fdc019c032439dceec9dcafdb7e1f4e7"
  },
  {
    "name": "0011_login_names.sql",
    "sql": "-- Control-plane migration 0011: sign-in names for people who have no email (ADR-025). Idempotent.\n-- Supabase Auth signs people in by email, so a person invited without an email gets a made-up address that nothing is ever sent to\n-- (login_email), and signs in with a short name instead (username). This table is the only place that links the two. It is global\n-- because a name must find exactly one person whichever company they belong to. The application is its only client: row security\n-- is on and the public API roles hold no privileges.\ncreate table if not exists public.login_names (\n  username      text primary key check (username ~ '^[a-z0-9][a-z0-9._-]{2,29}$'),\n  user_id       uuid not null unique,\n  login_email   text not null unique,\n  invitation_id uuid,                 -- the invitation that made it, so a half-finished set-up can be retried by the same link\n  created_at    timestamptz not null default now()\n);\n\nalter table public.login_names enable row level security;\ndo $$\ndeclare r text;\nbegin\n  foreach r in array array['anon', 'authenticated'] loop\n    if exists (select 1 from pg_roles where rolname = r) then execute format('revoke all on table public.login_names from %I', r); end if;\n  end loop;\nend $$;\n",
    "checksum": "876158914584a7c6f35f848fc804d7665037b314139bfb92e35b4cc15ad85086"
  }
